<script setup lang="ts">
  import { ref, useTemplateRef } from 'vue';
  import { vOnClickOutside } from '@vueuse/components';
  import type { OnClickOutsideOptions } from '@vueuse/core';
  import { tabNames, useMobilePgnStore, type TabName } from '@/stores/mobilePgn';
  import MobileMovesPopup from '@pgnMobile/MobileMovesPopup.vue';
  import MobileAnalysisPopup from './MobileAnalysisPopup.vue';
  import MobileFileListPopup from './MobileFileListPopup.vue';
  import MobileGameListPopup from './MobileGameListPopup.vue';
  import { usePgnNavigation } from '@/composables/pgnNavigation';

  const mobilePgn = useMobilePgnStore();
  const showTabSelectionModal = ref(false);
  function toggleTabSelectionModal() {
    showTabSelectionModal.value = !showTabSelectionModal.value;

    if (showTabSelectionModal.value) {
      showTabModalPanel.value = false;
    }
  }
  function closeTabSelectionModal() {
    showTabSelectionModal.value = false;
  }
  function toggleTabModalPanel() {
    showTabModalPanel.value = !showTabModalPanel.value;

    if (showTabModalPanel.value) {
      showTabSelectionModal.value = false;
    }
  }
  function closeTabModalPanel() {
    showTabModalPanel.value = false;
  }

  const showTabModalPanel = ref(false);

  function selectTab(tab: TabName) {
    mobilePgn.state.activeTab = tab;
    closeTabSelectionModal();
  }

  const openTabSelRef = useTemplateRef('openTabSelection');

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const onClickOutsideTabSelection: [(evt: any) => void, Omit<OnClickOutsideOptions, 'controls'>] =
    [
      () => {
        closeTabSelectionModal();
      },
      { ignore: [openTabSelRef] },
    ];

  const { goForward, goBack } = usePgnNavigation();
</script>

<template>
  <footer class="footer">
    <button
      ref="openTabSelection"
      class="burger-btn"
      @click="toggleTabSelectionModal"
    >
      ☰
    </button>
    <div
      v-if="showTabSelectionModal"
      v-on-click-outside="onClickOutsideTabSelection"
      class="modal-overlay"
      @click.self="closeTabSelectionModal"
    >
      <div class="modal-content tab-list">
        <button
          v-for="tab in tabNames"
          :key="tab"
          :class="{ active: mobilePgn.state.activeTab === tab }"
          @click="selectTab(tab)"
        >
          {{ tab }}
        </button>
      </div>
    </div>

    <button
      ref="openTabModalPanel"
      class="burger-btn"
      @click="toggleTabModalPanel"
    >
      ☰
    </button>
    <div
      v-if="showTabModalPanel"
      class="modal-overlay"
      @click.self="closeTabModalPanel"
    >
      <div class="modal-content tab-modal-content">
        <MobileMovesPopup
          v-if="mobilePgn.state.activeTab === 'Moves'"
          @close-popup="closeTabModalPanel"
        />
        <MobileAnalysisPopup
          v-if="mobilePgn.state.activeTab === 'Analysis'"
          @close-popup="closeTabModalPanel"
        />
        <MobileFileListPopup
          v-if="mobilePgn.state.activeTab === 'PGN Files'"
          @close-popup="closeTabModalPanel"
        />
        <MobileGameListPopup
          v-if="mobilePgn.state.activeTab === 'Game List'"
          @close-popup="closeTabModalPanel"
        />
      </div>
    </div>

    <button
      class="arrow-btn"
      @click="goBack"
    >
      ←
    </button>

    <button
      class="arrow-btn"
      @click="goForward"
    >
      →
    </button>
  </footer>
</template>

