<script setup lang="ts">
  import { usePgnStore } from '@/stores/pgn';

  import { usePgnEdit } from '@/composables/pgnEdit';
  import { nextTick } from 'vue';
  const pgnStore = usePgnStore();

  const emit = defineEmits<{
    closePopup: [void];
  }>();

  async function toggleCommentWrapper() {
    toggleComment();
    await nextTick();
    emit('closePopup');
  }

  const {
    toggleComment,
    formatNag,
    canPromote,
    toggleDelta,
    promoteVariation,
    toggleNag,
    deleteCurrentVariation,
    makeProblem,
  } = usePgnEdit();
</script>

<template>
  <div
    v-if="pgnStore.state.currentGame"
    class="actions"
  >
    <div class="action-row nag-row items-container">
      <button
        v-for="nag in [3, 2, 6, 4, 5, 1]"
        :key="nag"
        class="nag-btn"
        :class="{ active: pgnStore.currentNode?.nag == nag }"
        @click="toggleNag(nag)"
      >
        {{ formatNag(nag) }}
      </button>
    </div>

    <div
      v-if="pgnStore.state.currentGame.currentNode !== pgnStore.state.currentGame.root"
      class="action-row items-container"
    >
      <button
        v-if="pgnStore.currentNode"
        class="comment-btn"
        :title="pgnStore.currentNode.comment ? 'Remove Comment' : 'Add Comment'"
        @click="toggleCommentWrapper()"
      >
        {{ pgnStore.currentNode.comment ? 'Remove Comment' : 'Add Comment 💬' }}
      </button>

      <button
        class="promote-btn"
        :disabled="!canPromote"
        :title="
          !canPromote
            ? 'Cannot promote unless sub sub variation'
            : 'Make this move the primary variation'
        "
        @click="promoteVariation"
      >
        Promote ⬆️
      </button>
      <button
        class="delete-btn"
        :disabled="pgnStore.isMainline(pgnStore.state.currentGame.currentNode)"
        :title="
          pgnStore.isMainline(pgnStore.state.currentGame.currentNode)
            ? 'Cannot delete mainline moves'
            : ''
        "
        @click="deleteCurrentVariation"
      >
        Del Move 🗑️
      </button>

      <button @click="makeProblem">Make Problem 📝</button>

      <button @click="toggleDelta">Turn Delta {{ pgnStore.state.showDelta ? 'OFF' : 'ON' }}</button>
    </div>
  </div>
</template>

<style scoped lang="less">
  @import '@/style/shared.less';

  div.actions {
    display: flex;
    flex-direction: column;
    gap: 15px;
    align-items: center;

    button.comment-btn {
      background: #27ae60;

      &:hover {
        background: #2ecc71;
      }
    }
    button.delete-btn {
      .btn-danger();
    }
  }
</style>
