import { defineStore } from 'pinia';
import { reactive, computed, watch } from 'vue';

import { fenToBoard, getActiveColor } from './util/fen';
import type { BoardState, DbPgnGame, LegalMove, MinMaxEval } from './interfaces';

import type { PgnFile } from './interfaces';
import { useLoggerStore } from './logger';

import {
  type PgnNode,
  type ParsedPgnGame,
  generatePgn,
  isMainline,
  getPathToNode,
  getNodeByPath,
  getEvalsFromGame,
} from '@/util/pgn-tree';

import { calculateMissingPieces } from './util/material';

export const usePgnStore = defineStore('pgn', () => {
  const logger = useLoggerStore();

  const state = reactive({
    allPgnFiles: [] as PgnFile[],
    currentPgnFile: null as PgnFile | null,
    games: [] as DbPgnGame[],
    currentGame: null as ParsedPgnGame | null,

    isFlipped: false,

    //currently selected square index
    selectedIndex: null as number | null,
    legalMoves: [] as LegalMove[],

    //Show or not pawn score delta with best engine move
    showDelta: true,
    deltaInfo: '',

    //node uid
    editingCommentNodeId: null as string | null,
  });

  const currentPgnFilename = computed(() => {
    return state.currentPgnFile?.filename || 'No file selected';
  });

  const currentBoard = computed(() => {
    const game = state.currentGame;
    if (!game) {
      return Array(64).fill(null) as BoardState;
    }
    return fenToBoard(game.currentNode.fen);
  });

  const currentNode = computed(() => {
    const node = state.currentGame?.currentNode;

    if (!node) {
      return null;
    }

    return node;
  });

  const currentHalfMove = computed(() => {
    const node = currentNode;

    if (!node.value) {
      return 0;
    }

    if (node.value.moveNumber < 1) {
      return 0;
    }

    return (node.value.moveNumber - 1) * 2 + (node.value.turn == 'b' ? 1 : 0);
  });

  const currentGameEvals = computed(() => {
    if (!state.currentGame) {
      return [];
    }
    const retEvals: Array<MinMaxEval> = getEvalsFromGame(state.currentGame);

    return retEvals;
  });

  const currentFen = computed(() => {
    const game = state.currentGame;
    if (!game) {
      return 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';
    }

    return game.currentNode.fen;
  });

  const missingPieces = computed(() => {
    return calculateMissingPieces(currentFen.value);
  });

  const currentTurn = computed(() => {
    return getActiveColor(currentFen.value);
  });

  function restoreCurrentNode(): boolean {
    const game = state.currentGame;
    if (!game) {
      return false;
    }

    const savedPath = localStorage.getItem('currentPgnNodePath');
    if (!savedPath) {
      return false;
    }
    try {
      const path = JSON.parse(savedPath);
      if (!Array.isArray(path)) {
        return false;
      }
      const node = getNodeByPath(game.root, path);
      if (!node) {
        return false;
      }
      logger.info(`Setting current node to ${node.san} with fen\n ${node.fen}`);
      game.currentNode = node;
      return true;
    } catch (e) {
      logger.error('Failed to restore node path', e);
      return false;
    }
  }

  // Persist current node
  watch(
    () => state.currentGame?.currentNode,
    (newNode: PgnNode | undefined) => {
      if (!newNode) {
        return;
      }
      try {
        const path = getPathToNode(newNode);
        logger.debug(`saving current node path=[${path}]`);
        localStorage.setItem('currentPgnNodePath', JSON.stringify(path));
      } catch (e) {
        console.error('Failed to save node path', e);
      }
    },
  );

  function toggleFlip() {
    state.isFlipped = !state.isFlipped;
  }

  return {
    state,
    currentBoard,
    currentFen,
    currentTurn,

    restoreCurrentNode,

    isMainline,
    toggleFlip,
    generatePgn,

    currentPgnFilename,
    missingPieces,

    currentHalfMove,
    currentGameEvals,
    currentNode,
  };
});
