import { defineStore } from 'pinia';
import { reactive, watch } from 'vue';

export const tabNames = ['Game List', 'PGN Files', 'Moves', 'Analysis', 'Comments'] as const;

export type TabName = (typeof tabNames)[number];
const STORAGE_KEY = 'chess-mobile-pgn-active-tab';

export const useMobilePgnStore = defineStore('mobilePgn', () => {
  const state = reactive({
    activeTab: (localStorage.getItem(STORAGE_KEY) as TabName) || 'PGN Files',
  });

  // Load the last active tab from localStorage, default to 'game'

  // Save the active tab to localStorage whenever it changes
  watch(state, (state) => {
    localStorage.setItem(STORAGE_KEY, state.activeTab);
  });

  return { state };
});
