import { Chess, type PartialMove, type PieceSymbol } from 'chess.ts';

const FILES = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'];
const RANKS = ['8', '7', '6', '5', '4', '3', '2', '1'];

export function uciToIndex(uci: string): number {
  const file = uci[0];
  const rank = uci[1];
  if (!file || !rank) {
    throw new Error(`Invalid UCI: ${uci}`);
  }
  const col = FILES.indexOf(file);
  const row = RANKS.indexOf(rank);
  if (col === -1 || row === -1) {
    throw new Error(`Invalid UCI coordinate: ${uci}`);
  }
  return row * 8 + col;
}

export function indexToUci(index: number): string {
  if (index < 0 || index > 63 || !Number.isInteger(index)) {
    throw new Error(`Invalid index: ${index}`);
  }

  const row = Math.floor(index / 8);
  const col = index % 8;

  return FILES[col]! + RANKS[row];
}

export function calculateNextFen(fenBefore: string, uciMove: string): string {
  const board = new Chess(fenBefore);
  const move: PartialMove = {
    from: uciMove.substring(0, 2),
    to: uciMove.substring(2, 4),
  };
  if (uciMove.length > 4) {
    move.promotion = uciMove[4] as PieceSymbol;
  }
  board.move(move);
  return board.fen();
}
