<script setup lang="ts">
  import { ref, computed, onMounted } from 'vue';
  import { usePgnStore } from '@/stores/pgn';
  import { usePgnIO } from '@/composables/pgnIO';

  const emit = defineEmits<{
    closePopup: [void];
  }>();

  const pgnStore = usePgnStore();
  const { saveCurrentGame } = usePgnIO();

  const editedTags = ref<Record<string, string>>({});
  const showAddTagInput = ref(false);
  const newTagName = ref('');
  const showSuggestions = ref(false);

  // Standard PGN tags from the PGN specification
  const STANDARD_PGN_TAGS = [
    'Event',
    'Site',
    'Date',
    'Round',
    'White',
    'Black',
    'Result',
    'Annotator',
    'PlyCount',
    'TimeControl',
    'Time',
    'Termination',
    'Mode',
    'FEN',
    'SetUp',
    'WhiteElo',
    'BlackElo',
    'WhiteUSCF',
    'BlackUSCF',
    'WhiteNA',
    'BlackNA',
    'WhiteType',
    'BlackType',
    'EventDate',
    'EventSponsor',
    'Section',
    'Stage',
    'Board',
    'Opening',
    'Variation',
    'SubVariation',
    'ECO',
    'ECO',
    'NIC',
  ];

  const VALID_RESULTS = ['1-0', '0-1', '1/2-1/2', '*'];

  onMounted(() => {
    if (pgnStore.state.currentGame) {
      const tags: Record<string, string> = {};
      for (const [key, value] of pgnStore.state.currentGame.headers) {
        tags[key] = value;
      }
      editedTags.value = tags;
    }
  });

  const suggestedTags = computed(() => {
    const existingKeys = Object.keys(editedTags.value);
    return STANDARD_PGN_TAGS.filter((tag) => !existingKeys.includes(tag));
  });

  const filteredSuggestions = computed(() => {
    if (!newTagName.value) {
      return suggestedTags.value;
    }
    const search = newTagName.value.toLowerCase();
    return suggestedTags.value.filter((tag) => tag.toLowerCase().includes(search));
  });

  function getResultOptions() {
    const current = editedTags.value['Result'];
    if (current && !VALID_RESULTS.includes(current)) {
      return [...VALID_RESULTS, current];
    }
    return VALID_RESULTS;
  }

  async function saveTags() {
    if (!pgnStore.state.currentGame) {
      return;
    }

    // Update headers in the current game object
    const headers = new Map<string, string>();
    for (const [key, value] of Object.entries(editedTags.value)) {
      if (value.trim()) {
        headers.set(key, value);
      }
    }
    pgnStore.state.currentGame.headers = headers;
    pgnStore.state.currentGame.isDirty = true;

    await saveCurrentGame();
    emit('closePopup');
  }

  function showAddTag() {
    showAddTagInput.value = true;
    showSuggestions.value = true;
    newTagName.value = '';
  }

  function cancelAddTag() {
    showAddTagInput.value = false;
    showSuggestions.value = false;
    newTagName.value = '';
  }

  function selectTag(tagName: string) {
    newTagName.value = tagName;
    showSuggestions.value = false;
  }

  function confirmAddTag() {
    const tagName = newTagName.value.trim();
    if (tagName && !editedTags.value[tagName]) {
      editedTags.value[tagName] = '';
    }
    showAddTagInput.value = false;
    showSuggestions.value = false;
    newTagName.value = '';
  }

  function removeTag(key: string) {
    delete editedTags.value[key];
  }
</script>

<template>
  <div class="actions">
    <div
      v-if="pgnStore.state.currentGame"
      class="tags-editor"
    >
      <h3>Edit Game Tags</h3>
      <div class="tags-list">
        <div
          v-for="(value, key) in editedTags"
          :key="key"
          class="tag-row"
        >
          <label>{{ key }}:</label>
          <template v-if="key === 'Result'">
            <select
              v-model="editedTags[key]"
              :class="{ 'invalid-result': !VALID_RESULTS.includes(editedTags[key]!) }"
            >
              <option
                v-for="result in getResultOptions()"
                :key="result"
                :value="result"
                :class="{ 'invalid-option': !VALID_RESULTS.includes(result) }"
              >
                {{ result }}
              </option>
            </select>
          </template>
          <input
            v-else
            v-model="editedTags[key]"
            type="text"
          />
          <button
            class="remove-tag-btn"
            @click="removeTag(key as string)"
          >
            ✗
          </button>
        </div>
      </div>

      <!-- Add tag input with autocomplete -->
      <div
        v-if="showAddTagInput"
        class="add-tag-form"
      >
        <input
          v-model="newTagName"
          type="text"
          placeholder="Enter tag name..."
          @focus="showSuggestions = true"
          @keyup.enter="confirmAddTag"
          @keyup.escape="cancelAddTag"
        />

        <!-- Custom suggestions dropdown -->
        <div
          v-if="showSuggestions && filteredSuggestions.length > 0"
          class="suggestions-dropdown"
        >
          <div
            v-for="tag in filteredSuggestions"
            :key="tag"
            class="suggestion-item"
            @click="selectTag(tag)"
          >
            {{ tag }}
          </div>
        </div>

        <div class="add-tag-buttons">
          <button
            class="cancel-btn-small"
            @click="cancelAddTag"
          >
            Cancel
          </button>
          <button
            class="confirm-btn-small"
            @click="confirmAddTag"
          >
            Add
          </button>
        </div>
      </div>

      <button
        v-else
        class="add-tag-btn"
        @click="showAddTag"
      >
        + Add Tag
      </button>

      <div class="form-buttons items-container">
        <button
          class="cancel-btn"
          @click="emit('closePopup')"
        >
          Cancel
        </button>
        <button
          class="create-btn"
          @click="saveTags"
        >
          Save
        </button>
      </div>
    </div>
    <div
      v-else
      class="no-game"
    >
      No game selected.
    </div>
  </div>
</template>

