<script setup lang="ts">
  import { useChessStore } from '@/stores/problem';
  import type { ChessProblem } from '@/stores/interfaces';
  import { chessDb } from '@/stores/client_database';

  const store = useChessStore();
  const emit = defineEmits<{
    closeModal: [];
  }>();

  defineProps<{
    pgnTagsTooltip: string;
  }>();

  async function fetchNewProblem() {
    await store.fetchNextProblem(store.settings.newProblemId);
    emit('closeModal');
  }

  async function handleExportProblems() {
    const problems = await chessDb.problems.toArray();

    const blob = new Blob([JSON.stringify({ problems }, undefined, 4)], {
      type: 'application/json',
    });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'problems.json';
    a.click();
    URL.revokeObjectURL(url);
  }

  async function handleImportProblems() {
    const problemList: { problems: Array<ChessProblem> } = await new Promise((resolve, reject) => {
      const input = document.createElement('input');
      input.type = 'file';
      input.accept = 'application/json,.json';

      input.onchange = async () => {
        const file = input.files?.[0];
        if (!file) {
          return reject(new Error('No file selected'));
        }

        try {
          const text = await file.text();
          const json = JSON.parse(text);
          resolve(json);
        } catch (err) {
          reject(err);
        }
      };

      input.click();
    });

    await chessDb.storeProblems(problemList.problems);
    await store.updateProblemCount();
  }
</script>

<template>
  <div class="tab-pane">
    <span
      v-if="store.problem.blunder_move_san"
      class="first-move-info"
    >
      First attempt:
      <strong>{{ store.problem.blunder_move_san }}</strong>
      ({{ store.problem.blunder_move_eval?.toFixed(1) }}) vs ({{ store.problem.eval }})
    </span>

    <div
      v-if="store.problem.last_attempt"
      class="attempt-details"
    >
      <span class="last-seen">
        Last seen: {{ new Date(store.problem.last_attempt).toLocaleString() }}
      </span>
    </div>

    <div
      v-if="store.problem.status"
      class="current-status"
      :class="store.problem.status"
    >
      <span>Status: {{ store.problem.status === 'solved' ? 'Solved ✅' : 'Try Again 🔄' }}</span>
    </div>

    <div
      v-if="store.problem.pgn_filename"
      class="game-source-info"
    >
      <span class="pgn-file">
        Source:
        <strong>{{ store.problem.pgn_filename }}</strong>
      </span>

      <VTooltip :triggers="['hover', 'click']">
        <span class="game-index">
          Game Index:
          <strong>#{{ store.problem.game_index }}</strong>
          ℹ️
        </span>

        <template #popper>
          <span class="pgn-tags">{{ pgnTagsTooltip }}</span>
        </template>
      </VTooltip>
    </div>

    <div class="index-db">
      IndexDB Problem Count: Attempted {{ store.ui.filteredAttemptedDbProblemCount }} of
      {{ store.ui.filteredDbProblemCount }} Unfiltered:
      {{ store.ui.indexDbProblemCount }}

      <button @click="store.loadIndexDb()">Load</button>
      <button @click="handleExportProblems()">Export</button>
      <button @click="handleImportProblems()">Import</button>
    </div>

    <div class="problem-loader">
      <input
        id="new-problem-id"
        v-model.number="store.settings.newProblemId"
        type="number"
        min="0"
        step="1"
      />
      <button @click="fetchNewProblem">Load New Problem</button>
    </div>
  </div>
</template>

