<script setup lang="ts">
  import { usePgnStore } from '@/stores/pgn';
  import VariationNode from '@pgn/VariationNode.vue';
  import EvalChart from '@/components/EvalChart.vue';
  import { usePgnEdit } from '@/composables/pgnEdit';
  import { usePgnNavigation } from '@/composables/pgnNavigation';
  const pgnStore = usePgnStore();

  const {
    toggleComment,
    formatNag,
    canPromote,
    deleteCurrentVariation,
    promoteVariation,
    toggleDelta,
    toggleNag,
    goToNode,
    makeProblem,
  } = usePgnEdit();

  const { gotoHalfMove } = usePgnNavigation();
</script>

<template>
  <div class="pgn-variations-tab">
    <div
      v-if="pgnStore.state.currentGame"
      class="actions"
    >
      <div class="action-row nag-row items-container">
        <button
          v-for="nag in [3, 2, 6, 4, 5, 1]"
          :key="nag"
          class="nag-btn"
          :class="{ active: pgnStore.state.currentGame?.currentNode.nag == nag }"
          @click="toggleNag(nag)"
        >
          {{ formatNag(nag) }}
        </button>
      </div>

      <div
        v-if="pgnStore.state.currentGame.currentNode !== pgnStore.state.currentGame.root"
        class="action-row items-container"
      >
        <button
          class="comment-btn"
          :title="pgnStore.currentNode?.comment ? 'Remove Comment' : 'Add Comment'"
          @click="toggleComment()"
        >
          {{ pgnStore.currentNode?.comment ? 'Remove Comment' : 'Add Comment 💬' }}
        </button>

        <button
          class="promote-btn"
          :disabled="!canPromote"
          :title="
            !canPromote
              ? 'Cannot promote unless sub sub variation'
              : 'Make this move the primary variation'
          "
          @click="promoteVariation"
        >
          Promote ⬆️
        </button>
        <button
          class="delete-btn"
          :disabled="pgnStore.isMainline(pgnStore.state.currentGame.currentNode)"
          :title="
            pgnStore.isMainline(pgnStore.state.currentGame.currentNode)
              ? 'Cannot delete mainline moves'
              : ''
          "
          @click="deleteCurrentVariation"
        >
          Del Move 🗑️
        </button>

        <button @click="makeProblem">Make Problem 📝</button>

        <button @click="toggleDelta">
          Turn Delta {{ pgnStore.state.showDelta ? 'OFF' : 'ON' }}
        </button>
      </div>
    </div>

    <div class="moves-list">
      <VariationNode
        v-if="pgnStore.state.currentGame"
        :node="pgnStore.state.currentGame.root"
        :current-node="pgnStore.state.currentGame.currentNode"
        @navigate="goToNode"
      />
    </div>

    <EvalChart
      :evals="pgnStore.currentGameEvals"
      :current-move="pgnStore.currentHalfMove"
      @move-click="gotoHalfMove"
    />
  </div>
</template>

