<template>
  <div
    v-if="modelValue"
    class="modal-overlay"
    @click.self="close"
  >
    <div class="modal-content api-base-dialog">
      <h2>Configure API Server</h2>
      <p class="error-message">
        Unable to connect to the API server. Please configure the server base URL.
      </p>

      <div class="form-group">
        <label for="api-base-input">API Base URL:</label>
        <input
          id="api-base-input"
          v-model="currentValue"
          type="text"
          placeholder="e.g., http://localhost:8000/api"
          @keyup.enter="save"
        />
      </div>

      <div
        v-if="history.length > 0"
        class="history-section"
      >
        <label>Recent URLs:</label>
        <div class="history-list">
          <button
            v-for="(url, index) in history"
            :key="index"
            class="history-item"
            :class="{ active: currentValue === url }"
            @click="selectFromHistory(url)"
          >
            {{ url }}
          </button>
        </div>
      </div>

      <div class="button-group">
        <button
          class="btn btn-secondary"
          @click="close"
        >
          Cancel
        </button>
        <button
          class="btn btn-primary"
          @click="save"
        >
          Save & Retry
        </button>
      </div>
    </div>
  </div>
</template>

<script setup lang="ts">
  import { ref, watch } from 'vue';
  import { getApiBaseHistory, getApiBase } from '@/stores/problem';

  const props = defineProps<{
    modelValue: boolean;
  }>();

  const emit = defineEmits<{
    'update:modelValue': [value: boolean];
    save: [url: string];
  }>();

  const currentValue = ref('');
  const history = ref<string[]>([]);

  // Load history when dialog opens
  watch(
    () => props.modelValue,
    (isOpen) => {
      if (isOpen) {
        history.value = getApiBaseHistory();
        // Pre-fill with current API base if it exists
        const current = getApiBase();
        if (current && current !== 'api') {
          currentValue.value = current;
        } else if (history.value.length > 0) {
          currentValue.value = history.value[0]!;
        }
      }
    },
    { immediate: true },
  );

  function selectFromHistory(url: string) {
    currentValue.value = url;
  }

  function close() {
    emit('update:modelValue', false);
  }

  function save() {
    if (currentValue.value.trim()) {
      emit('save', currentValue.value.trim());
      close();
    }
  }
</script>

