import { Chess, type PartialMove, type PieceSymbol } from 'chess.ts';
import { getActiveColor } from '../stores/util/fen';
import type { Color, DbPgnGame, EvalEntry, MinMaxEval } from '@/stores/interfaces';
import {
  Node as ChessopsNode,
  ChildNode as ChessopsChildNode,
  type PgnNodeData,
  type Game as ChessopsGame,
  makePgn,
} from 'chessops/pgn';

export interface PgnNode {
  uid: string;
  san: string;
  uci: string;
  fen: string;
  comment: string | null;
  clock: string | null;
  emt: number | null; //estimated move time seconds

  nag: number | null;
  children: PgnNode[];
  parent: PgnNode | null;
  moveNumber: number;
  turn: Color;
  //0 mainline, 1 variation, 2 sub variation, 3 sub sub variation, etc.
  variationDepth: number;
  eval: EvalEntry | null;
}

export function createDefaultPgnNode(): PgnNode {
  //to not shallow copy array
  return {
    uid: '',
    san: '',
    uci: '',
    fen: '',
    comment: null,
    clock: null,
    emt: null,
    nag: null,
    children: [],
    parent: null,
    moveNumber: 0,
    turn: 'w',
    variationDepth: 0,
    eval: null,
  };
}

export interface ParsedPgnGame {
  dbEntry: DbPgnGame;

  root: PgnNode; // Initial state (no move)
  currentNode: PgnNode;
  headers: Map<string, string>;
  isDirty: boolean;
}

export interface FlatItem {
  id: string;
  type: 'move-pair' | 'single-move' | 'comment';
  depth: number;
  white?: PgnNode;
  black?: PgnNode;
  node?: PgnNode;
  text?: string;
  showEllipsis?: boolean;
}

// --- PGN Utilities ---

export function createPgnGameFromChessops(
  chessopsGame: ChessopsGame<PgnNodeData>,
  dbPgnGame: DbPgnGame,
): ParsedPgnGame {
  const startFen =
    chessopsGame.headers.get('FEN') || 'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1';

  const uidPrefix = `uid_${dbPgnGame.fileId}_${dbPgnGame.gameIndex}_`;

  const root: PgnNode = {
    ...createDefaultPgnNode(),
    uid: `${uidPrefix}0`,
    fen: startFen,
    children: [],
    variationDepth: -1,
    moveNumber: 0,
    turn: getActiveColor(startFen),
  };

  const game: ParsedPgnGame = {
    dbEntry: dbPgnGame,
    root,
    currentNode: root,
    headers: chessopsGame.headers,
    isDirty: false,
  };

  root.children = convertChessopsNodeIterative(chessopsGame.moves, root, uidPrefix);

  game.currentNode = root.children[0]!;

  return game;
}

export function addMove(game: ParsedPgnGame, uci: string): PgnNode | undefined {
  const chess = new Chess(game.currentNode.fen);
  const move = chess.move({
    from: uci.substring(0, 2),
    to: uci.substring(2, 4),
    promotion: uci.length > 4 ? (uci[4] as PieceSymbol) : undefined,
  });

  if (!move) {
    return;
  }

  // Check if move already exists in current node's children
  let nextNode = game.currentNode.children.find((c) => c.uci === uci);

  if (!nextNode) {
    nextNode = {
      //Not the regular uid structure, we'd need the node count,
      //perhaps keeping a ref to the root node and keeping total there
      //But on reload the uid's should get regenerated anyway
      ...createDefaultPgnNode(),
      uid: Math.random().toString(36).substring(7),
      san: move.san,
      uci,
      fen: chess.fen(),

      variationDepth: game.currentNode.variationDepth + 1,
      children: [],
      parent: game.currentNode,
      moveNumber: nextMoveNumber(game.currentNode),
      turn: move.color as Color,
    };
    game.currentNode.children.push(nextNode);
  }

  game.currentNode = nextNode;
  return nextNode;
}

export function setNag(node: PgnNode, nag: number | undefined) {
  if (!isSafeInteger(nag)) {
    node.nag = null;
    return;
  }
  if (nag < 1 || nag > 6) {
    node.nag = null;
  }
  node.nag = nag;
}

export function isSafeInteger(value: number | null | undefined): value is number {
  return Number.isSafeInteger(value);
}
export function isString(v: unknown): v is string {
  return typeof v === 'string';
}

export function nagToSymbol(nag: number): string {
  switch (nag) {
    case 1:
      return '!';
    case 2:
      return '?';
    case 3:
      return '!!';
    case 4:
      return '??';
    case 5:
      return '!?';
    case 6:
      return '?!';
    default:
      return '';
  }
}

export function isMainline(node: PgnNode): boolean {
  return node.variationDepth <= 0;
}

export function promoteNode(node: PgnNode): boolean {
  if (!node.parent) {
    return false;
  }

  // NOTE: We do not use isMainline() here because we want to allow promoting a sub-variation
  // even if its parent is NOT on the absolute mainline.
  // We only check if THIS node is the first child of its parent.
  const index = node.parent.children.indexOf(node);
  if (index <= 0) {
    return false;
  }

  const parent = node.parent;
  const mainline = parent.children[0];
  const variation = parent.children[index];

  parent.children[0] = variation!;
  parent.children[index] = mainline!;

  return true;
}

export function getPathToNode(node: PgnNode): number[] {
  const path: number[] = [];
  let current = node;
  while (current.parent) {
    const parent = current.parent;
    const index = parent.children.indexOf(current);
    if (index === -1) {
      throw new Error('Node not found in parent children');
    }
    path.unshift(index);
    current = parent;
  }
  return path;
}

export function getNodeByPath(root: PgnNode, path: number[]): PgnNode | null {
  let current = root;
  for (const index of path) {
    if (!current.children[index]) {
      return null;
    }
    current = current.children[index]!;
  }
  return current;
}

function extractClock(comment: string): { cleanComment: string; clock?: string } {
  const clockRegex = /\[%clk\s+([^\]]+)\]/g;
  let clock: string | undefined;
  const cleanComment = comment
    .replace(clockRegex, (_, p1) => {
      clock = p1;
      return '';
    })
    .trim();

  return { cleanComment, clock };
}
function extractEmt(comment: string): { cleanComment: string; emt: number | null } {
  const emtRegex = /\[%emt\s+([^\]]+)\]/g;
  let emtStr: string | undefined;
  const cleanComment = comment
    .replace(emtRegex, (_, p1) => {
      emtStr = p1;
      return '';
    })
    .trim();

  let emt = null;
  if (emtStr) {
    emt = parseFloat(emtStr);
  }

  return { cleanComment, emt };
}

function extractEval(comment: string): { cleanComment: string; evalEntry: EvalEntry | null } {
  const evalTagRe = new RegExp(
    [
      '\\[%eval', // literal "[%eval"
      '\\s+', // whitespace
      '(-?\\d+(?:\\.\\d+)?)', // score: int or decimal, optional minus
      '(?:', // optional ",<int>"
      ',',
      '\\s*',
      '(\\d+)', // depth
      '\\s*',
      ')?',
      '\\]', // closing "]"
    ].join(''),
    'g',
  );

  let evalStr: string | undefined;
  let depth: string | undefined;
  const cleanComment = comment
    .replace(evalTagRe, (_, p1, p2) => {
      evalStr = p1;
      depth = p2;
      return '';
    })
    .trim();

  if (!evalStr) {
    return { cleanComment, evalEntry: null };
  }

  return {
    cleanComment,
    evalEntry: {
      score: parseFloat(evalStr!),
      depth: parseIntOrNull(depth!) ?? 0,
    },
  };
}

//Just to strip it
function extractMateEval(comment: string): string {
  const evalTagRe = new RegExp(
    [
      '\\[%eval', // literal "[%eval"
      '\\s+', // whitespace
      '#',
      '[^\\]]+?', //everything until first ]
      '\\]', // closing "]"
    ].join(''),
    'g',
  );

  return comment.replace(evalTagRe, '');
}

function convertChessopsNodeIterative(
  root: ChessopsNode<PgnNodeData>,
  parentNode: PgnNode,
  uidPrefix: string,
): PgnNode[] {
  let nextNodeId = 0;
  const result: PgnNode[] = [];

  type StackItem = {
    chessopsNode: ChessopsChildNode<PgnNodeData>;
    parent: PgnNode;
    targetArray: PgnNode[];
    depth: number;
  };

  const stack: StackItem[] = [];

  // seed root children
  for (let i = root.children.length - 1; i >= 0; i--) {
    stack.push({
      chessopsNode: root.children[i]!,
      parent: parentNode,
      targetArray: result,
      depth: i === 0 ? 0 : 1,
    });
  }

  while (stack.length) {
    const { chessopsNode, parent, targetArray, depth } = stack.pop()!;
    const move = chessopsNode.data;

    const tempChess = new Chess(parent.fen);
    const m = tempChess.move(move.san);

    const rawComment = move.comments?.join('\n') || '';
    const clockRet = extractClock(rawComment);
    const emtRet = extractEmt(clockRet.cleanComment);
    const evalRet = extractEval(emtRet.cleanComment);

    const comment = trimToNull(extractMateEval(evalRet.cleanComment));

    ++nextNodeId;
    const newNode: PgnNode = {
      ...createDefaultPgnNode(),
      uid: `${uidPrefix}${nextNodeId}`,
      san: move.san,
      uci: m ? m.from + m.to + (m.promotion || '') : '',
      fen: tempChess.fen(),
      comment,
      nag: null,
      clock: trimToNull(clockRet.clock),
      emt: emtRet.emt,
      variationDepth: depth,
      children: [],
      parent,
      eval: evalRet.evalEntry,
      moveNumber: nextMoveNumber(parent),
      turn: m ? (m.color as Color) : 'w',
    };

    setNag(newNode, move.nags?.[0]);

    targetArray.push(newNode);

    // push children (reverse to preserve order)
    for (let i = chessopsNode.children.length - 1; i >= 0; i--) {
      stack.push({
        chessopsNode: chessopsNode.children[i]!,
        parent: newNode,
        targetArray: newNode.children,
        depth: i === 0 ? depth : depth + 1,
      });
    }
  }

  return result;
}

function nextMoveNumber(node: PgnNode): number {
  if (!node.parent) {
    return 1;
  }
  return node.turn === 'b' ? node.moveNumber + 1 : node.moveNumber;
}

export function generatePgn(game: ParsedPgnGame): string {
  const chessopsGame: ChessopsGame<PgnNodeData> = {
    headers: game.headers,
    moves: toChessopsNode(game.root),
  };
  return makePgn(chessopsGame);
}

function toChessopsNode(pgnNode: PgnNode): ChessopsNode<PgnNodeData> {
  const node = new ChessopsNode<PgnNodeData>();
  for (const child of pgnNode.children) {
    const comments: string[] = [];
    if (child.comment) {
      comments.push(child.comment);
    }
    if (child.clock) {
      comments.push(`[%clk ${child.clock}]`);
    }
    if (child.emt) {
      comments.push(`[%emt ${child.emt.toFixed(1)}]`);
    }
    if (child.eval) {
      comments.push(`[%eval ${child.eval.score.toFixed(2)},${child.eval.depth.toFixed(0)}]`);
    }

    const childNode = new ChessopsChildNode<PgnNodeData>({
      san: child.san,
      comments: comments.length > 0 ? comments : undefined,
      nags: isSafeInteger(child.nag) ? [child.nag] : undefined,
    });
    // Recursive conversion for grandkids
    const subConverted = toChessopsNode(child);
    childNode.children = subConverted.children;
    node.children.push(childNode);
  }
  return node;
}

export function trimToNull(s: string | undefined | null): string | null {
  if (!isString(s)) {
    return null;
  }
  const s2 = s.trim();
  if (s2 == '') {
    return null;
  }
  return s2;
}

export function parseIntOrNull(s: string | undefined): number | null {
  if (!s) {
    return null;
  }
  const parsedInt = parseInt(s);

  if (isSafeInteger(parsedInt)) {
    return parsedInt;
  }

  return null;
}

/**
 * Flattens a PGN tree into a linear list of display items.
 * Variations are interleaved into the sequence with incremented depth.
 */
export function flattenPgnTree(root: PgnNode, depth: number = 0): FlatItem[] {
  return flattenSequence(root.children, depth);
}

function flattenSequence(nodes: PgnNode[], depth: number): FlatItem[] {
  const items: FlatItem[] = [];
  let currentNodes = nodes;

  while (currentNodes.length > 0) {
    const main = currentNodes[0]!;
    const alts = currentNodes.slice(1);

    if (main.turn === 'w') {
      const black: PgnNode | undefined = main.children[0];

      // Check pairing: no comments on White, no alts for White, black exists, no comments on black
      if (
        main.comment === null &&
        alts.length === 0 &&
        black &&
        black.turn === 'b' &&
        black.comment === null
      ) {
        items.push({ id: `pair-${main.uid}`, type: 'move-pair', depth, white: main, black: black });

        // Alternatives of Black
        const actualBlackAlts = main.children.slice(1);
        for (const alt of actualBlackAlts) {
          items.push(...flattenSequence([alt], depth + 1));
        }
        currentNodes = black.children;
      } else {
        items.push({ id: `move-${main.uid}`, type: 'single-move', depth, node: main });
        if (main.comment) {
          items.push({
            id: `comment-${main.uid}`,
            type: 'comment',
            depth,
            text: main.comment,
            node: main,
          });
        }
        for (const alt of alts) {
          items.push(...flattenSequence([alt], depth + 1));
        }
        currentNodes = main.children;
      }
    } else {
      // Black move
      items.push({
        id: `move-${main.uid}`,
        type: 'single-move',
        depth,
        node: main,
        showEllipsis: true,
      });
      if (main.comment) {
        items.push({
          id: `comment-${main.uid}`,
          type: 'comment',
          depth,
          text: main.comment,
          node: main,
        });
      }
      for (const alt of alts) {
        items.push(...flattenSequence([alt], depth + 1));
      }
      currentNodes = main.children;
    }
  }

  return items;
}

export function addNewLines(pgn: string): string {
  // 1. Separate headers and body
  const headerMatch = pgn.match(/^(\s*\[[\s\S]*?\]\s*)+/);
  let headerPart = '';
  let bodyPart = pgn;

  if (headerMatch) {
    headerPart = headerMatch[0];
    bodyPart = pgn.slice(headerPart.length);
  }

  // 2. Trim body to remove leading/trailing whitespace
  const trimmedBody = bodyPart.trim();
  if (!trimmedBody) {
    return pgn; // No moves, just return original
  }

  // 3. Flatten whitespace in body (but be careful about comments?)
  // Simple approach: split by specific whitespace sequences
  // We want to preserve separation of tokens.
  const words = trimmedBody.split(/\s+/);

  // 4. Wrap text
  let currentLine = '';
  const lines: string[] = [];
  const limit = 80;

  for (const word of words) {
    if (!word) {
      continue;
    }

    if (currentLine.length + 1 + word.length > limit) {
      if (currentLine.length > 0) {
        lines.push(currentLine);
      }
      currentLine = word;
    } else {
      currentLine = currentLine.length > 0 ? currentLine + ' ' + word : word;
    }
  }

  if (currentLine.length > 0) {
    lines.push(currentLine);
  }

  const formattedBody = lines.join('\n');

  // Recombine
  // Ensure headers end with a newline before the body
  return headerPart.trimEnd() + '\n\n' + formattedBody;
}

export function getSan(uciMove: string, fen: string) {
  const board = new Chess(fen);
  const move: PartialMove = {
    from: uciMove.substring(0, 2),
    to: uciMove.substring(2, 4),
  };
  if (uciMove.length > 4) {
    move.promotion = uciMove[4] as PieceSymbol;
  }
  const result = board.move(move);
  if (result) {
    return result.san;
  }

  //fallback
  return uciMove;
}

export const MAX_CP = 4;
export function getEvalsFromGame(game: ParsedPgnGame): Array<MinMaxEval> {
  if (!game) {
    return [];
  }
  const retEvals: Array<MinMaxEval> = [];
  //let node: PgnNode | undefined = state.currentGame.root;
  const stack: Array<PgnNode> = [];
  stack.push(game.root);
  while (stack.length > 0) {
    const node = stack.pop()!;

    if (node.moveNumber > 0) {
      const halfMove = (node.moveNumber - 1) * 2 + (node.turn == 'b' ? 1 : 0);

      if (halfMove == retEvals.length) {
        retEvals.push({
          score: 0,
          max: -MAX_CP,
          min: MAX_CP,
        });
      }

      if (halfMove < 0 || halfMove >= retEvals.length) {
        throw new Error('order off');
      }

      if (node.eval) {
        retEvals[halfMove]!.max = Math.max(node.eval.score, retEvals[halfMove]!.max);
        retEvals[halfMove]!.min = Math.min(node.eval.score, retEvals[halfMove]!.min);

        if (node.variationDepth == 0) {
          retEvals[halfMove]!.score = node.eval.score;
        }
      }
    }
    for (const child of node.children) {
      stack.push(child);
    }
  }

  return retEvals;
}
