import type { BoardState, Color, PieceType } from '../interfaces';

export function getActiveColor(fenString: string): Color {
  const activeColor = fenString.split(' ')[1];

  if (!activeColor) {
    throw Error(`Invalid fen ${fenString}`);
  }

  // Update turn
  return activeColor as Color;
}

export function fenToBoard(fenString: string): BoardState {
  const newBoard: BoardState = Array(64).fill(null);
  const pieces = fenString.split(' ')[0];

  if (!pieces) {
    return newBoard;
  }
  let index = 0;
  for (const char of pieces) {
    if (char === '/') {
      continue;
    }
    if (/\d/.test(char)) {
      index += parseInt(char, 10);
    } else {
      const color: Color = char === char.toUpperCase() ? 'w' : 'b';
      const type = char.toLowerCase() as PieceType;
      newBoard[index] = { type, color };
      index++;
    }
  }
  return newBoard;
}
