<script setup lang="ts">
  import { ref, computed, onMounted, onUnmounted } from 'vue';
  import { useChessStore } from '@/stores/problem';
  import ChessBoard from '@/components/ChessBoard.vue';
  import HeaderButtons from '@problems/HeaderButtons.vue';
  import OptionsModal from '@problems/OptionsModal.vue';
  import LogViewer from '@/components/LogViewer.vue';
  import { useLoggerStore } from '@/stores/logger';
  import type { UseSwipeDirection } from '@vueuse/core';

  const store = useChessStore();
  const logger = useLoggerStore();
  const showOptions = ref(false);

  const pgnTagsTooltip = computed(() => {
    if (!store.problem.pgn_tags) {
      return '';
    }
    return Object.entries(store.problem.pgn_tags)
      .map(([key, value]) => `${key}: ${value}`)
      .join('\n');
  });

  function toggleOptions() {
    showOptions.value = !showOptions.value;
  }

  function handleKeydown(e: KeyboardEvent) {
    if (e.key === 'Escape') {
      showOptions.value = false;
    } else if (e.key === 'ArrowLeft') {
      store.undoMove();
    }
  }

  function handleSwipe(direction: UseSwipeDirection) {
    logger.info(`Swipe ${direction}`);
  }

  onMounted(() => {
    window.addEventListener('keydown', handleKeydown);
  });

  onUnmounted(() => {
    window.removeEventListener('keydown', handleKeydown);
  });

  const evalDiff = computed(() => {
    if (!store.problem) {
      return 0;
    }
    console.log(`Cur eval ${store.game.currentEval}  - ${store.problem.eval}`);
    const diff =
      (store.game.currentEval - (store.problem.eval ?? 0)) * (store.game.isFlipped ? -1 : 1);

    return diff;
  });
</script>

<template>
  <div class="problem-view main-container">
    <header class="header">
      <div class="items-container">
        <span
          v-if="store.problem.id !== -1"
          class="problem-id"
        >
          <span class="label">v1.016 Prob</span>
          <span class="value">#{{ store.problem.id }}</span>
        </span>

        <span
          v-if="store.game.currentEval !== undefined"
          class="eval-display"
          :class="{ positive: evalDiff > -0.75, negative: evalDiff <= -0.75 }"
        >
          Eval diff {{ evalDiff.toFixed(1) }}
          {{ store.game.missingPieces.pointDisparity }}
          <span class="white-pieces">{{ store.game.missingPieces.white.join('') }}</span>
          <span class="black-pieces">{{ store.game.missingPieces.black.join('') }}</span>
        </span>
      </div>

      <HeaderButtons @toggle-options="toggleOptions" />
    </header>

    <OptionsModal
      v-if="showOptions"
      :pgn-tags-tooltip="pgnTagsTooltip"
      @close="showOptions = false"
    />

    <div class="board-wrapper">
      <ChessBoard
        :board="store.game.board"
        :fen="store.game.fen"
        :is-flipped="store.game.isFlipped"
        :selected-index="store.ui.selectedIndex"
        :legal-moves="store.ui.legalMoves"
        :hint="store.ui.hint"
        :last-move="store.ui.lastMove"
        @square-click="store.selectSquare"
        @swipe="handleSwipe"
      />
    </div>

    <LogViewer />
  </div>
</template>

