<script setup lang="ts">
  import { usePgnIO } from '@/composables/pgnIO';
  import type { DbPgnGame } from '@/stores/interfaces';
  import { usePgnStore } from '@/stores/pgn';
  import { onMounted, watch, type ComponentPublicInstance } from 'vue';

  const pgnStore = usePgnStore();

  const { loadGame, deleteGame } = usePgnIO();

  const gameRefs = new Map<number, HTMLElement>();
  function setRef(el: Element | ComponentPublicInstance | null, game: DbPgnGame) {
    if (el) {
      gameRefs.set(game.gameIndex, el as HTMLElement);
    } else {
      gameRefs.delete(game.gameIndex);
    }
  }

  function scrollToNode(game: DbPgnGame | undefined) {
    if (!game) {
      return;
    }
    const el = gameRefs.get(game.gameIndex);
    if (el) {
      el.scrollIntoView({
        behavior: 'smooth',
        block: 'nearest',
        inline: 'nearest',
      });
    }
  }

  watch(
    () => pgnStore.state.currentGame,
    (newNode) => {
      // Use requestAnimationFrame or nextTick (flush: 'post' handles nextTick mostly)
      // to ensure DOM is ready if it's a new node.
      scrollToNode(newNode?.dbEntry);
    },
    { flush: 'post' },
  );

  onMounted(() => {
    scrollToNode(pgnStore.state.currentGame?.dbEntry);
  });
</script>

<template>
  <div class="pgn-game-list-tab">
    <div class="game-list">
      <div
        v-for="(game, index) in pgnStore.state.games"
        :key="game.gameIndex"
        :ref="(el) => setRef(el, game)"
        class="game-item"
        :class="{ active: game.gameIndex === pgnStore.state.currentGame?.dbEntry.gameIndex }"
        @click="loadGame(game)"
      >
        <div class="game-info">
          <VTooltip :triggers="['hover', 'click']">
            <div class="game-title">
              <div
                v-if="game.userTitle"
                class="user-title"
              >
                {{ game.userTitle }}
              </div>
              <div
                class="system-title"
                :class="{ 'with-user-title': game.userTitle }"
              >
                {{ index }}. {{ game.title || 'Untitled Game' }}
              </div>
            </div>
            <span
              v-if="
                game.gameIndex === pgnStore.state.currentGame?.dbEntry.gameIndex &&
                pgnStore.state.currentGame.isDirty
              "
              class="dirty-indicator"
            >
              *
            </span>

            <template #popper>
              <span class="pgn-tags">{{ game.content.substring(0, 300) }}</span>
            </template>
          </VTooltip>
        </div>
        <button
          class="delete-btn"
          title="Delete Game"
          @click.stop="deleteGame(game)"
        >
          🗑️
        </button>
      </div>
    </div>
  </div>
</template>

