import type { EvalEntry } from '../interfaces';

//Note score is in color to move
export interface BestMoveReturn extends EvalEntry {
  uci: string;
}

export interface Thinking extends EvalEntry {
  multipv: number;

  uciMove: string;

  seldepth: number;
}

export interface PublicThinking extends Thinking {
  fen: string;
}

export type OperationType = 'initialize' | 'inf_calc' | 'best_move';

export abstract class Operation {
  public static __sequence = 0; // static counter shared across all subclasses

  public readonly sequence: number;

  //return true if done
  abstract handleWorkerMessage(line: string): boolean;

  abstract readonly type: OperationType;

  constructor(protected postMessage: (line: string) => void) {
    Operation.__sequence += 1;

    this.sequence = Operation.__sequence;
  }

  abstract start(): void;

  abstract tryCancel(): void;

  protected resolve!: (v: void) => void;
  protected reject!: (e: unknown) => void;

  readonly done = new Promise<void>((res, rej) => {
    this.resolve = res;
    this.reject = rej;
  });
}
