<script setup lang="ts">
  import { usePgnIO } from '@/composables/pgnIO';
  import { ref, useTemplateRef } from 'vue';
  import { usePgnStore } from '@/stores/pgn';
  import { vOnClickOutside } from '@vueuse/components';
  import { PGN_ROUTE } from '@/router';
  import ApiBaseDialog from '@/components/ApiBaseDialog.vue';

  import type { OnClickOutsideOptions } from '@vueuse/core';

  const pgnStore = usePgnStore();

  const showModal = ref(false);

  //we don't want the modal "double toggling" with respect to the click outside

  const toggleModalButtonRef = useTemplateRef('toggleModalButton');

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const onClickOutsideModal: [(evt: any) => void, Omit<OnClickOutsideOptions, 'controls'>] = [
    () => {
      closeModal();
    },
    { ignore: [toggleModalButtonRef] },
  ];

  function toggleModal() {
    showModal.value = !showModal.value;
  }

  function closeModal() {
    showModal.value = false;
  }

  const {
    handleExport,
    handleImport,
    saveCurrentGame,
    handleCopyCurrentGame,
    importGameFromPastedText,

    uploadAll,
    downloadAll,
    showApiBaseDialog,
    retryWithNewApiBase,
  } = usePgnIO();
</script>

<template>
  <header class="header">
    <div
      v-if="pgnStore.state.currentGame"
      class="game-meta"
    >
      {{ pgnStore.state.currentGame.dbEntry.title }}
      <div class="points">
        {{ pgnStore.missingPieces.pointDisparity }}
        <span class="white-pieces">{{ pgnStore.missingPieces.white.join('') }}</span>
        <span class="black-pieces">{{ pgnStore.missingPieces.black.join('') }}</span>
      </div>
    </div>

    <!-- Menu Button -->
    <button
      ref="toggleModalButton"
      class="menu-btn"
      @click="toggleModal"
    >
      ⋯
    </button>

    <!-- Modal -->
    <div
      v-if="showModal"
      v-on-click-outside="onClickOutsideModal"
      class="modal-overlay"
    >
      <div class="modal-content">
        <div class="filename">
          {{ pgnStore.currentPgnFilename }}
        </div>

        <button
          class="mini-btn"
          @click="$router.push('/')"
        >
          Problems ↩️
        </button>
        <button
          class="mini-btn"
          @click="$router.push(`/${PGN_ROUTE}`)"
        >
          Non Mobile UI ↩️
        </button>

        <button
          class="save-btn"
          :disabled="!pgnStore.state.currentGame || !pgnStore.state.currentGame.isDirty"
          @click="saveCurrentGame"
        >
          Save to DB 💾
        </button>
        <button @click="handleExport">Export PGN 📤</button>
        <label class="import-btn">
          Import PGN 📥
          <input
            type="file"
            accept=".pgn"
            style="display: none"
            @change="handleImport"
          />
        </label>
        <button @click="pgnStore.toggleFlip">Flip Board 🔄</button>
        <button
          :disabled="!pgnStore.state.currentGame"
          @click="handleCopyCurrentGame"
        >
          Copy Game 📋
        </button>

        <button
          class="new-game-btn"
          title="Paste game from clipboard"
          @click="importGameFromPastedText"
        >
          Paste Game 📋
        </button>

        <button
          title="Upload all"
          @click="uploadAll"
        >
          Upload All ☁️⬆️
        </button>

        <button
          title="Download all"
          @click="downloadAll"
        >
          Download All ☁️⬇️
        </button>
      </div>
    </div>

    <!-- API Base Configuration Dialog -->
    <ApiBaseDialog
      v-model="showApiBaseDialog"
      @save="retryWithNewApiBase"
    />
  </header>
</template>

