<script setup lang="ts">
  import { useChessStore } from '@/stores/problem';

  const store = useChessStore();

  const emit = defineEmits<{
    closeModal: [];
  }>();

  function copyFEN() {
    store.copyFEN().then();
  }

  function getHint() {
    store.fetchHint();
    emit('closeModal');
  }
</script>

<template>
  <div class="tab-pane">
    <div class="option-item">
      <label for="engine-time">
        Engine Think Time:
        <strong>{{ store.settings.engineTime.toFixed(1) }}s</strong>
      </label>
      <input
        id="engine-time"
        v-model.number="store.settings.engineTime"
        type="range"
        min="0.1"
        max="10.0"
        step="0.1"
      />
    </div>

    <div class="divider" />

    <div class="action-section">
      <h4>Engine Actions</h4>
      <div class="button-group items-container">
        <button @click="getHint">💡 Get Hint</button>
        <button
          title="Copy FEN to clipboard"
          @click="copyFEN"
        >
          📋 Copy FEN
        </button>
      </div>
    </div>
  </div>
</template>

<style scoped lang="less">
  @import '@/style/shared.less';
</style>
